const reconstructThumbnailAttemptObjectKeys = `-- name: ReconstructThumbnailAttemptObjectKeys :many
SELECT a.asset_key, COALESCE(NULLIF(a.publish_lease_token, ''), a.version) AS version, o.file_name FROM foghorn.thumbnail_task_object o
JOIN foghorn.thumbnail_task_assignment a ON a.attempt_id = o.attempt_id WHERE o.attempt_id = $1
`

type ReconstructThumbnailAttemptObjectKeysRow struct {
	AssetKey string `db:"asset_key" json:"asset_key"`
	Version  string `db:"version" json:"version"`
	FileName string `db:"file_name" json:"file_name"`
}

func (q *Queries) ReconstructThumbnailAttemptObjectKeys(ctx context.Context, attemptID string) ([]ReconstructThumbnailAttemptObjectKeysRow, error) {
	rows, err := q.db.QueryContext(ctx, reconstructThumbnailAttemptObjectKeys, attemptID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ReconstructThumbnailAttemptObjectKeysRow{}
	for rows.Next() {
		var i ReconstructThumbnailAttemptObjectKeysRow
		if err := rows.Scan(&i.AssetKey, &i.Version, &i.FileName); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

